function compute(inputs) {
  const Q = inputs.Q;
  const K = inputs.K;
  const V = inputs.V;
  const scale = inputs.scale;
  const dk = K[0].length;
  const sqrt_dk = Math.sqrt(dk);
  const scaleFactor = scale ? 1 / sqrt_dk : 1;
  const n = Q.length;
  const m = K.length;
  const scores = [];
  for (let i = 0; i < n; i++) {
    scores[i] = [];
    for (let j = 0; j < m; j++) {
      let dot = 0;
      for (let k = 0; k < dk; k++) {
        dot += Q[i][k] * K[j][k];
      }
      scores[i][j] = dot * scaleFactor;
    }
  }
  const weights = [];
  for (let i = 0; i < n; i++) {
    const row = scores[i];
    const maxScore = Math.max(...row);
    const exps = row.map(s => Math.exp(s - maxScore));
    const sumExps = exps.reduce((a, b) => a + b, 0);
    weights[i] = exps.map(e => e / sumExps);
  }
  const output = [];
  for (let i = 0; i < n; i++) {
    output[i] = [];
    for (let d = 0; d < V[0].length; d++) {
      let sum = 0;
      for (let j = 0; j < m; j++) {
        sum += weights[i][j] * V[j][d];
      }
      output[i][d] = sum;
    }
  }
  const tableRows = [];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      tableRows.push([
        `q${i+1}, k${j+1}`,
        scores[i][j].toFixed(3),
        weights[i][j].toFixed(3),
        (weights[i][j] * V[j][0]).toFixed(3),
        (weights[i][j] * V[j][1]).toFixed(3)
      ]);
    }
  }
  const table = {
    columns: ['pair', 'score', 'weight', 'weight*V1', 'weight*V2'],
    rows: tableRows
  };
  const rowSums = weights.map(row => row.reduce((a, b) => a + b, 0));
  const maxWeight = Math.max(...weights.flat());
  const minWeight = Math.min(...weights.flat());
  let insight = '';
  if (maxWeight > 0.9) {
    insight = 'One weight is very high (>0.9), so the output is almost entirely that value vector.';
  } else if (maxWeight - minWeight < 0.1) {
    insight = 'All weights are similar, so the output is close to the average of the value vectors.';
  } else {
    insight = 'Weights are moderately spread; the output mixes the value vectors.';
  }
  if (!scale) {
    insight += ' Without scaling, scores are larger, making the softmax more peaked.';
  } else {
    insight += ' With scaling, scores are divided by sqrt(d_k), keeping the softmax smoother.';
  }
  return {
    scores: scores,
    weights: weights,
    output: output,
    table: table,
    rowSums: rowSums,
    insight: insight
  };
}
